# LAW-EPI-007 — Consensus-Illusion Detection

**Failure model.** N agents agreeing is evidence only proportional to their independence. Correlated panels (shared pretraining, shared retrieval corpus, shared context/scratchpad, sequential visibility, one poisoned source) produce unanimous *wrong* answers that look like consensus. The law refuses to let agreement certify anything in the lattice unless independence is measured along four axes — **evidence overlap, lineage correlation, rationale-path diversity, external grounding** — and at least one non-correlated verification channel confirms the claim. Core invariant: **no consensus certifies without external grounding.**

---

## 1. The LAW record (lands in `mag/law.py`)

```python
# mag/law.py -- addition
from mag.laws.epi007_consensus_illusion import violated as epi007_violated
from mag.laws.epi007_consensus_illusion import enforce as epi007_enforce

register(Law(
    id="LAW-EPI-007",

    trigger=Trigger(
        events=("aggregate.complete",       # a consensus verdict was emitted
                "invariant.promote",        # a lattice node is being promoted
                "pre.mutate"),              # a mutating op cites consensus justification
        scope=("node.kind == 'consensus_claim'"
               " or edge.label == 'justified_by:consensus'"),
    ),

    condition=epi007_violated,   # ctx -> bool : consensus claimed but not certifiable

    action=epi007_enforce,       # ctx -> Verdict : certify | quarantine+resample | refute+deny

    guardrail=Guardrail(
        immutable=True,                          # loaded from signed manifest; no runtime edits
        bypass_requires="cap:epistemics.override@quorum:2",
        audit="audit://epistemics/consensus-illusion",   # append-only
        anti_gaming=(
            "RD computed on claim-bearing spans only (padding does not raise diversity)",
            "evidence canonicalized server-side; client-supplied citation strings untrusted",
            "panel membership frozen+hashed at aggregate.start; late additions void the claim",
            "self-confidence ignored unless calibrator Brier <= 0.15 over last 200 graded claims",
            "override needs 2 distinct principals; node carries permanent override_ref",
        ),
    ),

    tier=Tier.ENFORCING,   # auto-escalates to CRITICAL when gating a state-mutating op
))
```

---

## 2. Detector module — `mag/laws/epi007_consensus_illusion.py`

```python
"""LAW-EPI-007: separate true agreement from N correlated hallucinations."""

import hashlib, itertools
from dataclasses import dataclass

# ---- pinned thresholds (change => new manifest signature) --------------------
MIN_PANEL          = 3      # fewer members => "consensus" claim invalid outright
MIN_AGREE_FRAC     = 2/3    # supermajority within one semantic equivalence class
EV_JACCARD_HARD    = 0.90   # effectively one source
EV_JACCARD_SOFT    = 0.60   # correlated sourcing
LINEAGE_MEAN_MAX   = 0.50   # tolerated mean pairwise lineage similarity
LINEAGE_DECORR     = 0.25   # "provably decorrelated" ceiling
RD_MIN             = 0.15   # rationale-path diversity floor
RD_DECORR          = 0.30   # diversity sufficient to soften a missing oracle
COPY_SIM           = 0.95   # near-verbatim rationales => copying, not converging
CIR_MAX            = 0.35   # composite Consensus-Illusion Risk ceiling
BYTE_IDENTICAL_MAX = 1      # >1 byte-identical answers w/ shared context => hard flag
W_EV, W_LIN, W_EG, W_RD, W_OC = 0.30, 0.20, 0.25, 0.15, 0.10   # CIR weights, sum=1

# ---- primitives --------------------------------------------------------------
def _pairwise_mean(pairs_fn, items):
    vals = [pairs_fn(a, b) for a, b in itertools.combinations(items, 2)]
    return sum(vals) / len(vals)

def evidence_jaccard(members):
    """Mean pairwise Jaccard over canonical evidence ids (URLs normalized,
    tool-call signatures, chunk hashes). High => everyone read the same thing."""
    return _pairwise_mean(lambda a, b: _jac(a.evidence_canon(), b.evidence_canon()),
                          members)

def _jac(A, B):
    U = A | B
    return len(A & B) / len(U) if U else 0.0

LINEAGE_KEYS = ("base_model", "finetune", "system_prompt_hash",
                "toolset_hash", "context_seed")

def lineage_similarity(members):
    """Mean pairwise fraction of shared lineage keys. All-same-base-model
    panel => 1.0 => statistically one model, N copies."""
    return _pairwise_mean(
        lambda a, b: sum(getattr(a.lineage, k) == getattr(b.lineage, k)
                         for k in LINEAGE_KEYS) / len(LINEAGE_KEYS),
        members)

def rationale_diversity(claim, members, embed, cos):
    """1 - mean pairwise cosine over CLAIM-BEARING spans only (dependency-parse
    filter: spans sharing >=1 lemma with the claim predicate). Prevents gaming
    by padding irrelevant text."""
    vecs = [embed(" ".join(claim_spans(m.rationale, claim))) for m in members]
    sims = [cos(vecs[i], vecs[j])
            for i, j in itertools.combinations(range(len(vecs)), 2)]
    return 1.0 - (sum(sims) / len(sims))

def external_grounding(claim, members, oracles, ledger):
    """1.0 iff ANY member's claim instance passes a deterministic oracle
    (sandbox exec / z3 equivalence / DB lookup), OR >=2 members' top evidence
    items are DISTINCT after canonicalization AND intact per the source ledger.
    Fabricated-ledger hits poison this to 0.0."""
    for m in members:
        if any(e in ledger.fabricated for e in m.evidence_canon()):
            return 0.0
    for m in members:
        if oracles.try_verify(claim.canonical_form(), m) is True:
            return 1.0
    tops = {m.top_evidence_canon() for m in members} - {None}
    good = {t for t in tops if ledger.intact(t)}
    return 1.0 if len(good) >= 2 else 0.0

# ---- semantic equivalence (code-as-law aware) ---------------------------------
def equivalent(a, b):
    ha, hb = canonical_hash(a), canonical_hash(b)   # alpha-renamed AST / folded literals
    if ha == hb:
        return True, "strong"
    if z3_iff_unsat(a, b):                          # Not(Iff(a,b)) unsat under forall-closure
        return True, "strong"
    if normalized_tokens(a) == normalized_tokens(b):
        return True, "weak"                         # weak equivalence can never yield PASS
    return False, "none"

def majority_class_size(claim, members):
    return sum(1 for m in members if equivalent(claim.answer, m.answer)[0])

# ---- evaluation ----------------------------------------------------------------
@dataclass
class Scorecard:
    k: int; n: int; ev_jac: float; lineage: float; rd: float
    eg: float; cir: float; hard_flags: tuple; disposition: str

def evaluate(ctx) -> Scorecard:
    claim   = ctx.node
    members = ctx.panel_members(claim)          # frozen at aggregate.start (hashed)
    n, k    = len(members), majority_class_size(claim, members)
    flags   = []

    if n < MIN_PANEL:
        flags.append("PANEL_TOO_SMALL")

    if k / max(n, 1) >= MIN_AGREE_FRAC and n >= MIN_PANEL:
        ev    = evidence_jaccard(members)
        lin   = lineage_similarity(members)
        rd    = rationale_diversity(claim, members, ctx.embed, ctx.cos)
        eg    = external_grounding(claim, members, ctx.oracles, ctx.ledger)
        conf  = ctx.calibrated_confidence(members)      # 0.5 default if uncalibrated
        oc    = conf * (1.0 - eg)
        cir   = W_EV*ev + W_LIN*lin + W_EG*(1-eg) + W_RD*(1-rd) + W_OC*oc

        if ev >= EV_JACCARD_HARD:                 flags.append("ONE_SOURCE")
        if ev >= EV_JACCARD_SOFT:                 flags.append("CORRELATED_SOURCING")
        if lin > LINEAGE_MEAN_MAX:                flags.append("SHARED_LINEAGE")
        if rd < RD_MIN:                           flags.append("PATH_MONOCULTURE")
        if any(cos_rationale_pair(members) >= COPY_SIM for _ in [0]):
                                                  flags.append("VERBATIM_COPY")
        if byte_identical_dupes(members) > BYTE_IDENTICAL_MAX \
           and ctx.shared_context(members):       flags.append("BYTE_IDENTICAL_SHARED_CTX")
        if lin >= 1.0 and eg == 0.0:              flags.append("EFFECTIVE_N_EQUALS_1")

        decorrelated = (ev <= 0.20 and lin <= LINEAGE_DECORR and rd >= RD_DECORR)
        if flags:
            disp = "HARD"
        elif cir > 0.60 or (eg == 0.0 and not decorrelated):
            disp = "HARD"
        elif cir > CIR_MAX or eg == 0.0:
            disp = "SOFT"
        else:
            disp = "PASS"
    else:
        ev = lin = rd = eg = cir = 0.0
        disp = "HARD" if "PANEL_TOO_SMALL" in flags else "NOT_A_CONSENSUS_CLAIM"

    return Scorecard(k, n, ev, lin, rd, eg, cir, tuple(flags), disp)

# ---- law interface ---------------------------------------------------------------
def violated(ctx) -> bool:
    sc = evaluate(ctx)
    if ctx.event == "pre.mutate":
        return sc.disposition != "PASS" or not justification_path_clean(ctx.node)
    return sc.disposition in ("HARD", "SOFT")

def enforce(ctx) -> Verdict:
    sc = evaluate(ctx)
    mutates = ctx.event == "pre.mutate"

    if sc.disposition == "PASS":
        ctx.node.stamp(certified_by="LAW-EPI-007", scorecard=sc)
        return Verdict.allow(scorecard=sc)

    if sc.disposition == "SOFT":
        ctx.node.quarantine(status="UNVERIFIED")
        ctx.bus.emit("resample.request", RESAMPLE_PROTOCOL(ctx))
        if mutates:
            return Verdict.deny(reason="mutation justified by UNVERIFIED consensus")
        return Verdict.annotate(status="UNVERIFIED", scorecard=sc)

    # HARD
    ctx.node.mark(status="REFUTED_CORRELATED", scorecard=sc)
    ctx.incident.open(kind="consensus_illusion", flags=sc.hard_flags, scorecard=sc)
    if mutates:
        return Verdict.deny(halt=True, escalate_tier=Tier.CRITICAL,
                            reason=f"correlated-consensus justification: {sc.hard_flags}")
    return Verdict.strip_claim(node=ctx.node, scorecard=sc)

def justification_path_clean(node) -> bool:
    return all(a.status == "CERTIFIED" and a.certified_by == "LAW-EPI-007"
               for a in ctx.lattice.ancestors(node, label="justified_by"))

RESAMPLE_PROTOCOL_TMPL = {
    "isolation":  "fresh sandbox per member; no shared kv-cache, no shared scratchpad",
    "prompt":     "paraphrase_matrix[i % len(paraphrase_matrix)]  # per-member paraphrase",
    "sampling":   {"temperature": 0.8, "top_p": 0.95, "seed": "per_member_nonce"},
    "routing":    "distinct tool endpoints per member; pairwise-disjoint URL allowlists",
    "visibility": "members blinded to each other and to round-1 outputs",
    "min_new_evidence": 1,
